package org.apache.commons.codec.binary;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for org.apache.commons.codec.binary.StringUtils.newStringIso8859_1(byte[])
 */
public class StringUtils_newStringIso8859_1_TriageGen1Test {

    @Test
    public void testNewStringIso8859_1_NormalString() {
        byte[] input = "Hello World".getBytes(StandardCharsets.ISO_8859_1);
        String expected = "Hello World";
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals("The string should be correctly decoded using ISO-8859-1", expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_SpecialCharacters() {
        // ISO-8859-1 specific characters: © (0xA9), ® (0xAE), ñ (0xF1)
        byte[] input = new byte[]{(byte) 0xA9, (byte) 0xAE, (byte) 0xF1};
        String expected = "©®ñ";
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals("The string should correctly handle ISO-8859-1 specific bytes", expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_EmptyArray() {
        byte[] input = new byte[0];
        String expected = "";
        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals("An empty byte array should return an empty string", expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_NullInput() {
        // Note: The implementation new String(bytes, Charsets.ISO_8859_1) 
        // will throw a NullPointerException if bytes is null.
        try {
            StringUtils.newStringIso8859_1(null);
        } catch (NullPointerException e) {
            // Expected behavior for standard Java String constructor with null byte array
        }
    }

    @Test
    public void testNewStringIso8859_1_AllBytes() {
        // Test with all possible byte values (0-255)
        byte[] input = new byte[256];
        for (int i = 0; i < 256; i++) {
            input[i] = (byte) i;
        }

        String actual = StringUtils.newStringIso8859_1(input);
        assertEquals("The length of the string should match the length of the byte array", 256, actual.length());

        // Verify a specific character from the middle
        // 0xA9 in ISO-8859-1 is ©
        assertEquals('©', actual.charAt(0xA9));
    }
}
